{
  "findings": [
    {
      "check_id": "CKV_AWS_21",
      "title": "S3 bucket policy contains a syntax error",
      "resource": "aws_s3_bucket_policy.pass3",
      "severity": "CRITICAL",
      "explanation": "The S3 bucket policy has a syntax error: a missing comma after the 'Principal' block. This will cause the policy to be invalid and fail to apply, potentially leaving the bucket without the intended access controls."
    }
  ],
  "patched_code": "resource "aws_s3_bucket_policy" "pass3" {
  bucket = "bucket"

  policy = <<POLICY
        {
            "Id": "Policy1597273448050",
            "Version": "2012-10-17",
            "Statement": [
                {
                    "Sid": "Stmt1597273446725",
                    "Action": [
                        "s3:GetObject"
                    ],
                    "Resource": "arn:aws:s3:::bucket/*",
                    "Principal": {
                        "AWS": "some_arn"
                    },
                    "Effect": "Deny"
                }
            ]
        }
        POLICY
}",
  "fix_summary": "Fixed a syntax error in the S3 bucket policy by adding a missing comma after the 'Principal' block, ensuring the policy is valid and can be applied."
}
